/// <summary>
/// CB705 4/9/2024 - This method will swap account (credit and debit)
/// </summary>
/// <param name = "_amount">_amount</param>
/// <param name = "_dimension">_dimension</param>
/// <param name = "_groupByDimension">groupByDimension</param>
public void createDocumentLine(Amount _amount, DimensionDefault _dimension, boolean _groupByDimension)
{
    LedgerJournalTable JournalTableData;

    next createDocumentLine(_amount, _dimension, _groupByDimension);

    if (this.parmRebateDateTrans().TAMRebateTable().METEnableVendorPayBack)
    {
        if (this.getDocumentHeader().tableId ==  tableNum(LedgerJournalTable))
        {
            JournalTableData = this.getDocumentHeader();
        }
        METSwapJournalAccountCode::swapAccountCode(JournalTableData.JournalNum);
    }
}

/// <summary>
/// CB201_RebatesExtension_GSTchanges
/// Get Source transaction tax item group
/// </summary>
/// <returns>TaxItemGroup of source tramsactions</returns>
protected TaxItemGroup getTaxItemGroup()
{
    TaxItemGroup taxItemGroup = next getTaxItemGroup();

    if (rebateTransactionType == TAMRebateTransactionType::Rebate && this.getRebatePosting().METFollowTransItemGSTGroup == NoYes::Yes)
    {
        taxItemGroup = this.parmItemSalesTaxGroup();

    }
    return taxItemGroup;
}
